import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Flow: sustainable rhythm","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/combat/flow.md","filePath":"en/guide/combat/flow.md"}'),l={name:"en/guide/combat/flow.md"};function n(o,t,s,d,h,c){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="flow-sustainable-rhythm" tabindex="-1">Flow: sustainable rhythm <a class="header-anchor" href="#flow-sustainable-rhythm" aria-label="Permalink to &quot;Flow: sustainable rhythm&quot;">​</a></h1><p><strong>Status:</strong> Experimental numeric profile · Not implemented.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Flow rewards a steady Modern rhythm with small Experimental efficiency benefits.</li><li>It grants no raw damage or accuracy bonus and never bypasses recovery.</li><li>Pauses clear Flow without punishing inactivity; Legacy uses automatic cadence instead.</li></ul><p>Flow rewards a forgiving, steady Modern rhythm. It is not a perfect-BPM challenge, and extra button presses never bypass recovery.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Stamina</th><th>Recovery</th><th>Meaning</th></tr></thead><tbody><tr><td>Off Rhythm</td><td>+5%</td><td>+5%</td><td>Rushed inputs reduce efficiency</td></tr><tr><td>Stable</td><td>Normal</td><td>Normal</td><td>Ordinary play</td></tr><tr><td>Flow</td><td>−5%</td><td>−5%</td><td>Three steady intervals earn the next-action benefit</td></tr></tbody></table><p>These are Experimental factors before final rounding and other modifiers. Consistency cues change qualitatively; there is no raw damage or accuracy bonus from Flow.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Input spacing</th><th>Result</th></tr></thead><tbody><tr><td>85–135% of the action&#39;s reference rhythm</td><td>Normal interval; builds a streak</td></tr><tr><td>70–under 85%</td><td>Slightly rushed; streak clears</td></tr><tr><td>Under 70%</td><td>Off Rhythm; additional rush costs</td></tr><tr><td>Over 135%</td><td>Pause; clears Flow without punishing inactivity</td></tr></tbody></table><ul><li>Reference rhythm comes from the previous action&#39;s wind-up, active phase and 1.5× base recovery.</li><li>Three unavailable presses within 500 ms trigger Off Rhythm, not extra attacks.</li><li>A large swing between consecutive non-pause intervals also enters Off Rhythm; ordinary pauses are not punished.</li><li>Three Normal intervals restore Stable from Off Rhythm; another three enter Flow.</li><li>Feints, defense, target changes and weapon/mode changes reset the streak.</li><li>Legacy uses automatic cadence instead of Flow.</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>Longsword Basic Slash has a 1300 ms reference rhythm. A 1200 ms follow-up is Normal; a 1000 ms follow-up is Slightly rushed and costs more. Availability still gates both.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/combat/stamina-and-reactive-combat.html">Stamina</a> · <a href="/Syrolands-Public/en/game-design/combat/numeric-prototype.html#flow-test">Exact state and rounding rules</a> · <a href="/Syrolands-Public/en/game-design/combat/flow.html">Full Flow design</a></p><p><span id="flow-rhythm-without-button-mashing"></span></p>',16)])])}const f=e(l,[["render",n]]);export{u as __pageData,f as default};
